// ===== BTC Buy-Zone scoring — ported from btc-buy-zone-gauge.html =====
// Alerts ONLY on state transitions (dedup via workflow static data).

const fngData = $('Fear & Greed').first().json;
const dailyK = $('Daily Klines').all().map(i => i.json);
const h4K = $('4H Klines').all().map(i => i.json);

// Binance klines: each row = [openTime, open, high, low, close, ...]. n8n may deliver
// rows as items (json per row) or one item containing the whole array — handle both.
const rows = (k) => (Array.isArray(k[0]) ? k : (k.length === 1 && Array.isArray(k[0].data) ? k[0].data : k.map(r => Object.values(r))));
const dailyCloses = rows(dailyK).map(r => parseFloat(r[4]));
const h4Closes = rows(h4K).map(r => parseFloat(r[4]));

const fng = parseInt(fngData.data[0].value, 10);
const fngLabel = fngData.data[0].value_classification;
const price = dailyCloses[dailyCloses.length - 1];

// ---------- helpers ----------
const avg = a => a.reduce((x, y) => x + y, 0) / a.length;
function ema(a, n) { const k = 2 / (n + 1); let e = avg(a.slice(0, n)); for (let i = n; i < a.length; i++) e = a[i] * k + e * (1 - k); return e; }
function weeklyStochRSI(daily) {
  const wk = []; for (let i = daily.length - 1; i >= 0; i -= 7) wk.unshift(daily[i]);
  const n = 14, out = []; let ag = 0, al = 0;
  for (let i = 1; i <= n; i++) { const c = wk[i] - wk[i - 1]; ag += Math.max(c, 0); al += Math.max(-c, 0); }
  ag /= n; al /= n; out.push(100 - 100 / (1 + (al ? ag / al : 1e9)));
  for (let i = n + 1; i < wk.length; i++) {
    const c = wk[i] - wk[i - 1];
    ag = (ag * (n - 1) + Math.max(c, 0)) / n; al = (al * (n - 1) + Math.max(-c, 0)) / n;
    out.push(100 - 100 / (1 + (al ? ag / al : 1e9)));
  }
  const rec = out.slice(-14), lo = Math.min(...rec), hi = Math.max(...rec);
  return hi > lo ? (out[out.length - 1] - lo) / (hi - lo) * 100 : 50;
}

// ---------- Panel 1: accumulation score ----------
const ma200 = avg(dailyCloses.slice(-200));
const ema21d = ema(dailyCloses, 21);
const stoch = weeklyStochRSI(dailyCloses);
const fngScore = fng <= 5 ? 100 : fng <= 10 ? 92 : fng <= 20 ? 75 : fng <= 30 ? 60 : fng <= 45 ? 42 : fng <= 60 ? 28 : fng <= 75 ? 15 : 5;
const stochScore = 100 - stoch;
const vs200 = (price - ma200) / ma200 * 100;
const maScore = vs200 <= -20 ? 100 : vs200 <= -10 ? 85 : vs200 <= 0 ? 70 : vs200 <= 10 ? 50 : vs200 <= 25 ? 30 : 12;
const vs21 = (price - ema21d) / ema21d * 100;
const emaScore = vs21 <= 0 ? 85 : vs21 <= 3 ? 70 : vs21 <= 8 ? 45 : vs21 <= 15 ? 25 : 10;
const score = Math.round(fngScore * 0.40 + stochScore * 0.30 + maScore * 0.15 + emaScore * 0.15);
const zoneOf = s => s >= 80 ? 'DEPLOY' : s >= 60 ? 'STRONG_BUY' : s >= 40 ? 'NEUTRAL' : 'EXTENDED';
const zone = zoneOf(score);

// ---------- Panel 2: trade setup per timeframe ----------
function tfSetup(closes) {
  const p = closes[closes.length - 1];
  const m200 = avg(closes.slice(-200));
  const e21 = ema(closes, 21);
  const above200 = p > m200;
  const emaAbove = e21 > m200;
  const dist21 = (p - e21) / e21 * 100;
  const mingling = Math.abs(dist21) <= 1.5;
  const spread = Math.abs(e21 - m200) / m200 * 100;
  return { setup: above200 && emaAbove && mingling, compressed: spread < 5, above200, dist21: dist21.toFixed(1), spread: spread.toFixed(1) };
}
const d = tfSetup(dailyCloses.slice(-260));
const h = tfSetup(h4Closes);
const setupState = d.setup && h.setup ? 'BOTH' : d.setup ? 'DAILY' : h.setup ? 'H4' : 'NONE';

// ---------- transition detection (dedup) ----------
const sd = $getWorkflowStaticData('global');
const prev = sd.btcAlerts || { zone: null, setupState: null, fngExtreme: false };
const alerts = [];
const px = '$' + Math.round(price).toLocaleString('en-US');

if (zone !== prev.zone && prev.zone !== null) {
  const up = ['EXTENDED', 'NEUTRAL', 'STRONG_BUY', 'DEPLOY'];
  const improving = up.indexOf(zone) > up.indexOf(prev.zone);
  if (zone === 'DEPLOY') alerts.push({ priority: 'max', tags: 'rotating_light,moneybag', title: 'BTC: DEPLOY RESERVES ZONE', msg: `Accumulation score ${score}/100 — max-fear zone. F&G ${fng} (${fngLabel}), stochRSI ${stoch.toFixed(0)}, price ${px} (${vs200.toFixed(1)}% vs 200d MA).` });
  else if (zone === 'STRONG_BUY') alerts.push({ priority: 'high', tags: 'chart_with_downwards_trend,moneybag', title: 'BTC: Strong Buy Zone ' + (improving ? 'entered' : '(pulled back from Deploy)'), msg: `Accumulation score ${score}/100. F&G ${fng} (${fngLabel}), price ${px}.` });
  else alerts.push({ priority: 'default', tags: 'information_source', title: `BTC zone: ${prev.zone} → ${zone}`, msg: `Accumulation score ${score}/100. F&G ${fng}, price ${px}.` });
}

const fngExtreme = fng <= 10;
if (fngExtreme && !prev.fngExtreme) {
  alerts.push({ priority: 'max', tags: 'scream', title: 'BTC: Fear & Greed \u2264 10', msg: `F&G hit ${fng} (${fngLabel}) — framework extreme-fear trigger. Check 2-week stochRSI (currently ${stoch.toFixed(0)}) for confluence. Price ${px}.` });
}

if (setupState !== prev.setupState && prev.setupState !== null && setupState !== 'NONE') {
  const pr = setupState === 'BOTH' ? 'max' : 'high';
  const label = setupState === 'BOTH' ? 'SETUP ON DAILY + 4H' : `Setup on ${setupState === 'H4' ? '4H' : 'Daily'} only (reduced size)`;
  alerts.push({ priority: pr, tags: 'dart', title: 'BTC trade: ' + label, msg: `21EMA+200MA conditions met. Daily: ${d.setup ? 'SETUP' : 'no'}${d.compressed ? ' (compressed)' : ''}, dist21 ${d.dist21}%. 4H: ${h.setup ? 'SETUP' : 'no'}${h.compressed ? ' (compressed)' : ''}, dist21 ${h.dist21}%. Wait for candle-BODY close breakout before entry. Price ${px}.` });
}

sd.btcAlerts = { zone, setupState, fngExtreme };

return alerts.length
  ? alerts.map(a => ({ json: a }))
  : [{ json: { priority: null, title: 'no-alert', msg: `score ${score} zone ${zone} setup ${setupState} fng ${fng}` } }];
